        {
            return Err(PyErr::new::<PyValueError, _>(
                "Scope hosts must contain at most 10000 non-empty hostnames of 253 bytes each",
            ));
        }

        Ok(Self {
            roe_id,
            scope_hosts,
            allow_lsass,
            allow_sam,
        })
