impl CredentialExtractor {
    fn require_scoped_target(&self, target: Option<&str>) -> PyResult<()> {
        let target = target.ok_or_else(|| {
            PyErr::new::<PyValueError, _>("An explicit scoped target is required")
        })?;
        if target.trim().is_empty() || target.len() > MAX_HOST_BYTES || !self.is_in_scope(target) {
            return Err(PyErr::new::<PyValueError, _>("Target not in scope"));
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Credential {
    pub cred_type: String,
    pub username: String,
    pub domain: String,
    pub hash: String,
    pub source: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_extractor_creation() {
        let extractor = CredentialExtractor::new(
            "ROE-TEST".to_string(),
            Some(vec!["192.168.1.1".to_string()]),
            false,
            false,
        );
        assert!(extractor.is_ok());
    }
    #[test]
    fn test_credential_extractor_requires_roe_id() {
        let result = CredentialExtractor::new("".to_string(), None, false, false);
        assert!(result.is_err(), "Empty ROE ID must be rejected");

        let result = CredentialExtractor::new("   ".to_string(), None, false, false);
        assert!(result.is_err(), "Whitespace-only ROE ID must be rejected");
    }

    #[test]
    fn test_extract_lsass_blocked_without_permission() {
        let extractor = CredentialExtractor::new(
            "ROE-TEST".to_string(),
            Some(vec!["192.168.1.1".to_string()]),
            false, // allow_lsass = false
            false,
        )
        .expect("Valid CredentialExtractor construction");
        let result = extractor.extract_from_lsass(Some("192.168.1.1"));
        assert!(
            result.is_err(),
            "LSASS extraction must be blocked when allow_lsass=false"
        );
    }

    #[test]
    fn test_permitted_placeholders_do_not_report_false_success() {
        let extractor = CredentialExtractor::new(
            "ROE-TEST".to_string(),
            Some(vec!["host.example".to_string()]),
            true,
            true,
        )
        .expect("Valid CredentialExtractor construction");
        assert!(extractor.extract_from_lsass(None).is_err());
        assert!(extractor.extract_from_lsass(Some("other.example")).is_err());
        assert!(extractor.extract_from_lsass(Some("host.example")).is_err());
        assert!(extractor.extract_from_sam("sam.hive", None).is_err());
        assert!(extractor
            .extract_from_sam("sam.hive", Some("host.example"))
            .is_err());
        assert!(extractor.parse_dcc(&[]).is_err());
        assert!(extractor.parse_dcc(&[0_u8; 16]).is_err());
    }
}
